const express = require('express');
const { SQSClient, ReceiveMessageCommand, SendMessageCommand, DeleteMessageCommand } = require('@aws-sdk/client-sqs');
const { Invoice } = require('../models/invoice');

const app = express();
app.use(express.json());

const sqs = new SQSClient({ region: 'eu-central-1' });
const DLQ_URL = process.env.BILLING_DLQ_URL;
const MAIN_QUEUE_URL = process.env.BILLING_MAIN_QUEUE_URL;

app.post('/api/billing/dlq/redrive/:invoiceId', async (req, res) => {
  if (!req.user || !req.user.merchantId) {
    return res.status(401).json({ error: 'Merchant authentication required' });
  }

  // Ensure invoice exists and belongs to the authenticated merchant
  const invoice = await Invoice.findOne({
    where: {
      id: req.params.invoiceId,
      merchantId: req.user.merchantId
    }
  });

  if (!invoice) {
    return res.status(403).json({ error: 'Access denied or invoice not found' });
  }

  const receiveCmd = new ReceiveMessageCommand({
    QueueUrl: DLQ_URL,
    MaxNumberOfMessages: 10,
    WaitTimeSeconds: 2
  });

  const dlqResponse = await sqs.send(receiveCmd);
  const messages = dlqResponse.Messages || [];

  const matchedMessage = messages.find(msg => {
    try {
      const body = JSON.parse(msg.Body);
      return body.invoiceId === req.params.invoiceId && body.merchantId === req.user.merchantId;
    } catch {
      return false;
    }
  });

  if (!matchedMessage) {
    return res.status(404).json({ error: 'No matching DLQ message found for invoice' });
  }

  await sqs.send(new SendMessageCommand({
    QueueUrl: MAIN_QUEUE_URL,
    MessageBody: matchedMessage.Body
  }));

  await sqs.send(new DeleteMessageCommand({
    QueueUrl: DLQ_URL,
    ReceiptHandle: matchedMessage.ReceiptHandle
  }));

  res.json({ status: 'REDRIVEN', invoiceId: req.params.invoiceId });
});

app.listen(3003);
